    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def make_async_wrapper(func):
    @wraps(func)
    async def wrapper(*args, **kwargs):
        return await func(*args, **kwargs)
    return wrapper

async def main():
    def sync_foo(): return 1

    f1 = foo
    f2 = sync_wrapper(foo)
    f3 = make_async_wrapper(sync_foo)
    f4 = partial(foo)
    f5 = partial(sync_wrapper(foo))

