                curr = curr.func
            elif hasattr(curr, "__wrapped__"):
                curr = curr.__wrapped__
            else:
                break
        return chain

    def is_coroutine_callable(call):
        for c in get_call_chain(call):
            if inspect.isroutine(c):
                if inspect.iscoroutinefunction(c):
